import { prisma } from '../lib/prisma.js'
import { ApiError } from '../utils/ApiError.js'

export async function listar(req, res) {
  const enderecos = await prisma.endereco.findMany({
    include: { usuario: { select: { id: true, nome: true, telefone: true } } },
    orderBy: { criadoEm: 'desc' },
  })
  res.json(enderecos)
}

export async function obter(req, res) {
  const endereco = await prisma.endereco.findUnique({
    where: { id: req.params.id },
    include: { usuario: { select: { id: true, nome: true, telefone: true } } },
  })
  if (!endereco) throw new ApiError(404, 'Endereço não encontrado.')
  res.json(endereco)
}

export async function criar(req, res) {
  const { usuarioId, cliente_id, apelido, rua, logradouro, numero, bairro, complemento, cidade, estado, uf, cep, latitude, longitude, distanciaKm } = req.body
  const dono = usuarioId || cliente_id
  const ruaFinal = rua || logradouro

  if (!dono || !ruaFinal || !bairro) throw new ApiError(400, 'Informe cliente, rua e bairro.')

  const cliente = await prisma.usuario.findFirst({ where: { id: dono, tipo: 'CLIENTE' }, select: { id: true } })
  if (!cliente) throw new ApiError(404, 'Cliente não encontrado.')

  const endereco = await prisma.endereco.create({
    data: {
      usuarioId: cliente.id,
      apelido: apelido || 'Endereço',
      rua: ruaFinal,
      numero: numero || null,
      bairro,
      complemento: complemento || null,
      cidade: cidade || '',
      estado: estado || uf || '',
      cep: cep || null,
      latitude: latitude != null ? Number(latitude) : null,
      longitude: longitude != null ? Number(longitude) : null,
      distanciaKm: distanciaKm != null ? Number(distanciaKm) : null,
    },
  })
  res.status(201).json(endereco)
}

export async function atualizar(req, res) {
  const { id } = req.params
  const data = { ...req.body }
  if (data.logradouro && !data.rua) data.rua = data.logradouro
  delete data.logradouro
  delete data.usuarioId
  delete data.cliente_id
  delete data.uf
  if (data.estado === undefined && req.body.uf !== undefined) data.estado = req.body.uf

  const endereco = await prisma.endereco.update({ where: { id }, data })
  res.json(endereco)
}

export async function remover(req, res) {
  await prisma.endereco.delete({ where: { id: req.params.id } })
  res.status(204).send()
}
